START TRANSACTION;
UPDATE creature_template SET npcflag=npcflag|3,ScriptName='npc_exiles_paladin_ghost' WHERE entry IN(162998,167179) AND AIName='' AND ScriptName IN('','npc_exiles_paladin_ghost');
