UPDATE creature_template SET faction=14,KillCredit1=175015,ScriptName='npc_exiles_gutgruk' WHERE entry=163036 AND AIName='' AND KillCredit1 IN(0,175015) AND ScriptName IN('','npc_exiles_gutgruk');
