-- Horde page lacks endpoint records: use the shared Ghost Wolf as the functional counterpart.
UPDATE gameobject_template SET ScriptName='go_exiles_necrotic_altar' WHERE entry=342068 AND AIName='' AND ScriptName IN('','go_exiles_necrotic_altar');
